local Horologist = {}
local PRODUCTS = {
    pocket_watch = { name = "Žepna ura", brassCost = 2, glassCost = 1, time = 14, cost = 200, accuracy = 0.70, prestige = 5, happiness = 2, description = "Prenosna ura." },
    table_clock = { name = "Mizna ura", brassCost = 3, woodCost = 2, glassCost = 1, time = 10, cost = 150, accuracy = 0.65, happiness = 2, description = "Ura za mizo." },
    carriage_clock = { name = "Potovalna ura", brassCost = 4, glassCost = 2, time = 12, cost = 300, accuracy = 0.75, prestige = 5, description = "Ura za potovanja." },
    marine_chronometer = { name = "Marinski kronometer", brassCost = 5, glassCost = 2, time = 30, cost = 1000, accuracy = 0.95, prestige = 20, knowledge = 20, description = "Za natančno navigacijo." },
    repeating_watch = { name = "Ponavljalna ura", brassCost = 3, goldCost = 1, time = 20, cost = 500, accuracy = 0.80, prestige = 10, happiness = 5, description = "Z zvoncem za ure." },
    royal_chronometer = { name = "Kraljevski kronometer", goldCost = 3, jewelCost = 2, glassCost = 2, time = 45, cost = 2000, accuracy = 0.99, prestige = 40, happiness = 12, description = "Najnatančnejša ura za kralja." },
}
local BUILDINGS = {
    workshop = { name = "Urarjeva delavnica", cost = { gold = 400, wood = 100, iron = 30 }, upkeep = 10, qualityBonus = 5 },
    watch_studio = { name = "Urarjev atelje", cost = { gold = 1500, wood = 200, stone = 300, brass = 50 }, upkeep = 35, qualityBonus = 25 },
    precision_lab = { name = "Laboratorij natančnosti", cost = { gold = 3000, wood = 300, stone = 600, brass = 100 }, upkeep = 60, qualityBonus = 35, prestigeBonus = 10 },
    royal_horologist = { name = "Kraljevski horolog", cost = { gold = 6000, wood = 400, stone = 1000, brass = 200, gold = 50 }, upkeep = 120, qualityBonus = 50, prestigeBonus = 25 },
}
Horologist.brassStock = 10; Horologist.glassStock = 8; Horologist.woodStock = 10; Horologist.goldStock = 3; Horologist.jewelStock = 2
Horologist.productStock = {}; Horologist.buildings = {}; Horologist.horologist = nil; Horologist.activeMaking = {}; Horologist.totalProducts = 0; Horologist.dayTimer = 0
function Horologist.init() Horologist.brassStock=10; Horologist.glassStock=8; Horologist.woodStock=10; Horologist.goldStock=3; Horologist.jewelStock=2; Horologist.productStock={}; Horologist.buildings={}; Horologist.horologist=nil; Horologist.activeMaking={}; Horologist.totalProducts=0; Horologist.dayTimer=0; print("[Horologist] Royal Horologist & Watchmaker System initialized (6 products, 4 buildings)") end
function Horologist.hireHorologist(n,s) s=s or math.random(45,90); local c=500+s*10; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; Horologist.horologist={name=n or ("Horolog "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Horolog najet: %s (spretnost: %d)",Horologist.horologist.name,s),"success") end; return true end
function Horologist.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function Horologist.build(id) local ok,e=Horologist.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(Horologist.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function Horologist.getQualityBonus() local b=0; for _,bd in ipairs(Horologist.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function Horologist.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.brassCost and Horologist.brassStock<(d.brassCost or 0) then return false,"Premalo medenine" end; if d.glassCost and Horologist.glassStock<(d.glassCost or 0) then return false,"Premalo stekla" end; if d.woodCost and Horologist.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.goldCost and Horologist.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and Horologist.jewelStock<(d.jewelCost or 0) then return false,"Premalo dragih kamnov" end; if #Horologist.buildings==0 then return false,"Potrebna delavnica" end; if not Horologist.horologist then return false,"Potreben horolog" end; return true end
function Horologist.make(pt) local ok,e=Horologist.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.brassCost then Horologist.brassStock=Horologist.brassStock-d.brassCost end; if d.glassCost then Horologist.glassStock=Horologist.glassStock-d.glassCost end; if d.woodCost then Horologist.woodStock=Horologist.woodStock-d.woodCost end; if d.goldCost then Horologist.goldStock=Horologist.goldStock-d.goldCost end; if d.jewelCost then Horologist.jewelStock=Horologist.jewelStock-d.jewelCost end; local t=d.time; if Horologist.horologist then t=math.max(2,t-math.floor(Horologist.horologist.skill/8)) end; table.insert(Horologist.activeMaking,{id="watch_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost,accuracy=d.accuracy or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,knowledge=d.knowledge or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %s (%d dni)",d.name,t),"info") end; return true end
function Horologist.completeMaking(m) local q=1.0+(Horologist.getQualityBonus()/100); if Horologist.horologist then q=q+(Horologist.horologist.skill/200) end; q=math.min(2.5,q); Horologist.productStock[m.productType]=(Horologist.productStock[m.productType] or 0)+1; Horologist.totalProducts=Horologist.totalProducts+1; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if m.knowledge>0 and _G.Culture then pcall(function() _G.Culture.knowledgePoints=(_G.Culture.knowledgePoints or 0)+m.knowledge end) end; if Horologist.horologist then Horologist.horologist.itemsMade=Horologist.horologist.itemsMade+1; if math.random()<0.15 then Horologist.horologist.skill=math.min(100,Horologist.horologist.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Ura izdelana: %s (kakovost: %.1f)",m.productName,q),"success") end end
function Horologist.update(dt) if not _G.state then return end; Horologist.dayTimer=Horologist.dayTimer+dt; if Horologist.dayTimer>=30 then Horologist.dayTimer=0; for i=#Horologist.activeMaking,1,-1 do local m=Horologist.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then Horologist.completeMaking(m); table.remove(Horologist.activeMaking,i) end end; local tu=0; for _,bd in ipairs(Horologist.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if Horologist.horologist then tu=tu+20 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function Horologist.getStats() return {brassStock=Horologist.brassStock,glassStock=Horologist.glassStock,goldStock=Horologist.goldStock,jewelStock=Horologist.jewelStock,productStock=Horologist.productStock,numBuildings=#Horologist.buildings,hasHorologist=Horologist.horologist~=nil,horologistName=Horologist.horologist and Horologist.horologist.name or "—",horologistSkill=Horologist.horologist and Horologist.horologist.skill or 0,activeMaking=#Horologist.activeMaking,totalProducts=Horologist.totalProducts} end
return Horologist
